 "content": "def transform(grid):
    """Repeat a motif along the axis marked by full monochrome divider lines."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Detect full-width or full-height lines, ignoring unmarked backgrounds.
    row_lines = [(r, grid[r][0]) for r in range(h)
                 if all(v == grid[r][0] for v in grid[r])]
    col_lines = [(c, grid[0][c]) for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))]

    # The divider orientation is the one with a repeated line color, or the
    # only available line orientation. In these puzzles, repeated separators
    # indicate the direction of motif repetition.
    def repeated_color(lines):
        counts = {}
        for _, color in lines:
            counts[color] = counts.get(color, 0) + 1
        return max(counts.values(), default=0)

    use_rows = repeated_color(row_lines) >= repeated_color(col_lines)
    if use_rows and row_lines:
        positions = [p for p, _ in row_lines]
        diffs = [b - a for a, b in zip(positions, positions[1:])]
        period = min(diffs) if diffs else positions[0] + 1
        if period <= 0:
            return out
        # Background is the most frequent color excluding divider rows.
        vals = [grid[r][c] for r in range(h) for c in range(w)
                if r not in positions]
        bg = max(set(vals), key=vals.count) if vals else 0
        template = [None] * period
        for r in range(h):
            if r in positions:
                continue
            off = r % period
            if template[off] is None:
                template[off] = [bg] * w
            for c, v in enumerate(grid[r]):
                if v != bg:
                    template[off][c] = v
        for r in range(h):
            if r in positions:
                continue
            vals = template[r % period]
            if vals is not None:
                out[r] = vals[:]
        return out

    if col_lines:
        positions = [p for p, _ in col_lines]
        diffs = [b - a for a, b in zip(positions, positions[1:])]
        period = min(diffs) if diffs else positions[0] + 1
        if period <= 0:
            return out
        vals = [grid[r][c] for r in range(h) for c in range(w)
                if c not in positions]
        bg = max(set(vals), key=vals.count) if vals else 0
        template = [None] * period
        for c in range(w):
            if c in positions:
                continue
            off = c % period
            if template[off] is None:
                template[off] = [bg] * h
            for r in range(h):
                v = grid[r][c]
                if v != bg:
                    template[off][r] = v
        for c in range(w):
            if c in positions:
                continue
            vals = template[c % period]
            if vals is not None:
                for r in range(h):
                    out[r][c] = vals[r]
    return out
